1	// Raft 跟随者本地日志复制：在单次命令调用内维护节点状态，顺序应用
2	// 领导者发来的 AppendEntries 请求。本文件只做纯逻辑处理，不连接网络。
3	package mevwatch
4	
5	import (
6		"fmt"
7	)
8	
9	// LogEntry 是一条日志：Index 从 1 开始连续编号，Term 为该条目写入时的任期，
10	// Command 为字符串命令。
11	type LogEntry struct {
12		Index   int    `json:"index"`
13		Term    int    `json:"term"`
14		Command string `json:"command"`
15	}
16	
17	// InitialState 是跟随者在本次调用开始时的状态。
18	type InitialState struct {
19		// CurrentTerm 是该节点已知的最新任期。
20		CurrentTerm int `json:"currentTerm"`
21		// CommittedIndex 是已经提交（不可覆盖）的最高日志索引。
22		CommittedIndex int `json:"committedIndex"`
23		// Log 是从索引 1 开始的连续日志。
24		Log []LogEntry `json:"log"`
25	}
26	
27	// AppendRequest 是顺序到达的一次日志复制请求。
28	type AppendRequest struct {
29		// Term 是领导者任期。
30		Term int `json:"term"`
31		// PrevLogIndex / PrevLogTerm 是新条目紧邻的前一条日志的索引与任期；
32		// 均为 0 表示日志起点（哨兵），不是真实条目。
33		PrevLogIndex int `json:"prevLogIndex"`
34		PrevLogTerm  int `json:"prevLogTerm"`
35		// Entries 是待追加的条目，必须从前一条索引加 1 开始连续排列，允许为空。
36		Entries []LogEntry `json:"entries"`
37		// LeaderCommit 是领导者已提交索引。
38		LeaderCommit int `json:"leaderCommit"`
39	}
40	
41	// AppendResult 是单条请求处理后节点对该请求的答复。
42	type AppendResult struct {
43		// Accepted 表示本次复制是否成功。
44		Accepted bool `json:"accepted"`
45		// Reason 是成功 ok 或被拒绝的具体原因。
46		Reason string `json:"reason"`
47		// Term 是处理后节点的当前任期（较高任期请求即便最终被拒绝也会留下任期更新）。
48		Term int `json:"term"`
49		// CommittedIndex 是处理后节点的已提交索引。
50		CommittedIndex int `json:"committedIndex"`
51		// AppliedIndex / ApplyError 仅在启用键值应用（ReplicateOptions.ApplyKV）
52		// 时填充：处理本请求后已应用的最高日志索引与首个应用错误。
53		// 复制是否被接受与命令应用是否失败相互独立表达。
54		AppliedIndex *int        `json:"appliedIndex,omitempty"`
55		ApplyError   *ApplyError `json:"applyError,omitempty"`
56		// applyFields 为 true 时 JSON 输出总是带上 appliedIndex 与 applyError
57		// （无错误时 applyError 为 null）；为 false 时两个字段完全不出现。
58		// 编解码规则见 applyfields.go。
59		applyFields bool
60	}
61	
62	// ReplicateOutput 是整次调用的结果。
63	type ReplicateOutput struct {
64		// Results 与输入请求一一对应。
65		Results []AppendResult `json:"results"`
66		// FinalTerm / FinalCommittedIndex 是最终状态。
67		FinalTerm           int `json:"finalTerm"`
68		FinalCommittedIndex int `json:"finalCommittedIndex"`
69		// FinalLog 是处理完所有请求后的完整日志。
70		FinalLog []LogEntry `json:"finalLog"`
71		// FinalAppliedIndex / FinalKV / FinalApplyError 仅在启用键值应用时填充：
72		// 最终已应用的最高日志索引、最终键值表与首个应用错误。没有请求时同样
73		// 反映初始已提交前缀的应用结果。
74		FinalAppliedIndex *int              `json:"finalAppliedIndex,omitempty"`
75		FinalKV           map[string]string `json:"finalKV,omitempty"`
76		FinalApplyError   *ApplyError       `json:"finalApplyError,omitempty"`
77		// applyFields 含义同 AppendResult.applyFields，编解码规则见 applyfields.go。
78		applyFields bool
79	}
80	
81	// 拒绝原因（稳定标识符，帮助文档中有说明）。
82	const (
83		ReasonOK                      = "ok"
84		ReasonStaleTerm               = "stale term: leader term is lower than current term"
85		ReasonRequestTermNegative     = "invalid request: term is negative"
86		ReasonPrevLogIndexNegative    = "invalid request: prevLogIndex is negative"
87		ReasonPrevLogTermNegative     = "invalid request: prevLogTerm is negative"
88		ReasonLeaderCommitNegative    = "invalid request: leaderCommit is negative"
89		ReasonEmptyEntryTerm          = "invalid request: log entry has zero term"
90		ReasonEntryIndexGap           = "invalid request: entries are not consecutive from prevLogIndex+1"
91		ReasonEntryTermDecreases      = "invalid request: entry terms are not non-decreasing"
92		ReasonEntryTermExceedsReqTerm = "invalid request: entry term exceeds request term"
93		ReasonPrevLogMismatch         = "prev log mismatch: entry at prevLogIndex is missing or has a different term"
94		ReasonCommandConflictSameTerm = "entry conflict: same index and term but different command"
95		ReasonWouldOverwriteCommitted = "would overwrite committed entry"
96	)
97	
98	type replicateState struct {
99		currentTerm    int
100		committedIndex int
101		log            []LogEntry // log[i].Index == i+1
102	}
103	
104	// ReplicateOptions 控制 Replicate 的可选行为。零值保持原有处理与输出。
105	type ReplicateOptions struct {
106		// ApplyKV 为 true 时把已提交命令解释为键值操作（set/delete），在本次
107		// 调用内从空键值表开始，随提交位置推进按日志次序逐条应用；为 false
108		// 时命令仍是不加解释的任意字符串。
109		ApplyKV bool
110	}
111	
112	// Replicate 校验初始状态并顺序应用全部复制请求，返回逐次结果与最终状态。
113	// 初始状态非法时返回错误（调用方应以非零退出码结束）。单条请求违反字段规则
114	// 时只记录一次拒绝、不改变任何状态，随后继续处理下一条请求。
115	func Replicate(initial InitialState, requests []AppendRequest) (ReplicateOutput, error) {
116		return ReplicateWithOptions(initial, requests, ReplicateOptions{})
117	}
118	
119	// ReplicateWithOptions 与 Replicate 相同，但可通过 ReplicateOptions 启用
120	// 可选行为（如键值应用）。
121	func ReplicateWithOptions(initial InitialState, requests []AppendRequest, opts ReplicateOptions) (ReplicateOutput, error) {
122		state, err := newReplicateState(initial)
123		if err != nil {
124			return ReplicateOutput{}, err
125		}
126	
127		var applier *kvApplier
128		if opts.ApplyKV {
129			applier = newKVApplier()
130			// 先按索引顺序应用初始日志中已提交的前缀，再顺序处理复制请求。
131			applier.applyUpTo(state.log, state.committedIndex)
132		}
133	
134		results := make([]AppendResult, 0, len(requests))
135		for _, request := range requests {
136			result := state.apply(request)
137			if applier != nil {
138				// 每条请求处理结束后，只应用新提交且尚未应用的日志；应用失败
139				// 不改变复制的接受与否、提交位置或拒绝原因。
140				applier.applyUpTo(state.log, state.committedIndex)
141				result.setApplyFields(applier.appliedIndex, applier.err)
142			}
143			results = append(results, result)
144		}
145		finalLog := append([]LogEntry{}, state.log...)
146		if finalLog == nil {
147			finalLog = []LogEntry{}
148		}
149		output := ReplicateOutput{
150			Results:             results,
151			FinalTerm:           state.currentTerm,
152			FinalCommittedIndex: state.committedIndex,
153			FinalLog:            finalLog,
154		}
155		if applier != nil {
156			output.setApplyFields(applier.appliedIndex, applier.kv, applier.err)
157		}
158		return output, nil
159	}
160	
161	func newReplicateState(initial InitialState) (replicateState, error) {
162		if initial.CurrentTerm < 0 {
163			return replicateState{}, fmt.Errorf("invalid initial state: currentTerm must be a non-negative integer")
164		}
165		if initial.CommittedIndex < 0 {
166			return replicateState{}, fmt.Errorf("invalid initial state: committedIndex must be a non-negative integer")
167		}
168		if initial.CommittedIndex > len(initial.Log) {
169			return replicateState{}, fmt.Errorf("invalid initial state: committedIndex %d exceeds log length %d", initial.CommittedIndex, len(initial.Log))
170		}
171		log := append([]LogEntry(nil), initial.Log...)
172		for i, entry := range log {
173			expected := i + 1
174			if entry.Index != expected {
175				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-consecutive index %d", expected, entry.Index)
176			}
177			if entry.Term <= 0 {
178				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-positive term %d", expected, entry.Term)
179			}
180			if i > 0 && entry.Term < log[i-1].Term {
181				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d is lower than previous term %d", expected, entry.Term, log[i-1].Term)
182			}
183			if entry.Term > initial.CurrentTerm {
184				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d exceeds currentTerm %d", expected, entry.Term, initial.CurrentTerm)
185			}
186		}
187		return replicateState{
188			currentTerm:    initial.CurrentTerm,
189			committedIndex: initial.CommittedIndex,
190			log:            log,
191		}, nil
192	}
193	
194	// termAt 返回索引 idx 处条目的任期；idx 为 0 时是日志起点哨兵，超出日志长度时 ok 为 false。
195	func (s *replicateState) termAt(idx int) (term int, ok bool) {
196		switch {
197		case idx == 0:
198			return 0, true
199		case idx < 0 || idx > len(s.log):
200			return 0, false
201		default:
202			return s.log[idx-1].Term, true
203		}
204	}
205	
206	// apply 处理单条请求。整个操作是原子的：任何拒绝都不会在日志、已提交索引上
207	// 留下部分变更；唯一例外是较高任期带来的 currentTerm 更新，按规则必须保留。
208	func (s *replicateState) apply(request AppendRequest) AppendResult {
209		snapshot := *s
210		accepted, reason := s.tryApply(request)
211		if !accepted {
212			// 回滚日志与提交位置；较高任期更新（若已发生）保留在 s.currentTerm 中。
213			s.log = snapshot.log
214			s.committedIndex = snapshot.committedIndex
215		}
216		return AppendResult{
217			Accepted:       accepted,
218			Reason:         reason,
219			Term:           s.currentTerm,
220			CommittedIndex: s.committedIndex,
221		}
222	}
223	
224	func (s *replicateState) tryApply(request AppendRequest) (bool, string) {
225		// 规则 1：先做字段合法性校验。违反字段规则的请求只记录拒绝、不改变任何
226		// 状态——即使它携带更高任期，也不能更新节点。
227		if reason := validateRequest(request); reason != ReasonOK {
228			return false, reason
229		}
230	
231		// 规则 2：较低任期直接拒绝，状态（含任期）完全不变。
232		if request.Term < s.currentTerm {
233			return false, ReasonStaleTerm
234		}
235	
236		// 规则 3：首条目任期不得低于前一条日志任期（整段日志必须不下降）。
237		// 这仍属于字段规则，放在任期更新之前：非法请求不能借高任期改变节点。
238		if len(request.Entries) > 0 && request.Entries[0].Term < request.PrevLogTerm {
239			return false, ReasonEntryTermDecreases
240		}
241	
242		// 规则 4：较高任期先更新当前任期，再核对日志；之后即便因前缀不匹配被拒，
243		// 任期更新也保留。
244		if request.Term > s.currentTerm {
245			s.currentTerm = request.Term
246		}
247	
248		// 规则 5：前一条日志必须存在且任期相同。索引 0 始终只与任期 0 匹配。
249		prevTerm, ok := s.termAt(request.PrevLogIndex)
250		if !ok || prevTerm != request.PrevLogTerm {
251			return false, ReasonPrevLogMismatch
252		}
253	
254		// 规则 6：把待追加条目与现有位置逐一比对——全部检查通过后才落笔，
255		// 保证“即使前面已发现可追加内容，也不能留下部分变更”。第一个任期冲突
256		// 位置之后的旧日志都会被整段替换，因此只需在冲突位置之前检查命令冲突。
257		// matched 是请求条目中与现有位置完全相同（同任期同命令）的连续前缀长度；
258		// 超出本地日志长度的位置尚不存在，不属于已匹配，稍后追加。
259		start := request.PrevLogIndex // entries[k] 对应索引 start+1+k
260		cutAt := -1                   // 首个任期不同的现有位置（切片下标）
261		matched := 0
262		for offset, incoming := range request.Entries {
263			idx := start + 1 + offset
264			if idx > len(s.log) {
265				break // 该位置及之后都不存在：稍后整体追加
266			}
267			existing := s.log[idx-1]
268			switch {
269			case existing.Term == incoming.Term && existing.Command == incoming.Command:
270				// 完全相同：保留，重复请求不会产生重复条目。
271				matched++
272			case existing.Term == incoming.Term:
273				// 同索引同任期却命令不同：拒绝，日志与提交位置保持原样。
274				return false, ReasonCommandConflictSameTerm
275			case idx <= s.committedIndex:
276				// 不同任期意味着要覆盖该处及其后缀；已提交条目不可覆盖。
277				return false, ReasonWouldOverwriteCommitted
278			default:
279				// 未提交位置上的任期冲突：截断到此处再追加，其后旧日志整段丢弃。
280				cutAt = idx - 1
281			}
282			if cutAt >= 0 {
283				break
284			}
285		}
286	
287		// 规则 7：合并日志。全部匹配的短请求（matched == len(entries)）不删除
288		// 本地多出的尾部；任期冲突时截断冲突位置及其后缀；其余缺失位置追加。
289		if cutAt >= 0 {
290			matched = cutAt - start
291			s.log = append([]LogEntry(nil), s.log[:cutAt]...)
292		}
293		if matched < len(request.Entries) {
294			s.log = append(s.log, request.Entries[matched:]...)
295		}
296	
297		// 规则 8：提交位置推进至 leaderCommit 与本次确认的最后索引的较小值，
298		// 且不会后退。空条目请求的确认位置就是前一条索引。
299		lastIndex := request.PrevLogIndex + len(request.Entries)
300		newCommit := request.LeaderCommit
301		if lastIndex < newCommit {
302			newCommit = lastIndex
303		}
304		if newCommit > s.committedIndex {
305			s.committedIndex = newCommit
306		}
307		return true, ReasonOK
308	}
309	
310	func validateRequest(request AppendRequest) string {
311		if request.Term < 0 {
312			return ReasonRequestTermNegative
313		}
314		if request.PrevLogIndex < 0 {
315			return ReasonPrevLogIndexNegative
316		}
317		if request.PrevLogTerm < 0 {
318			return ReasonPrevLogTermNegative
319		}
320		if request.LeaderCommit < 0 {
321			return ReasonLeaderCommitNegative
322		}
323		// 条目必须从前一条索引加 1 开始连续排列；任期为正、沿请求条目自身
324		// 不下降，且不得超过请求（领导者）任期。与 prevLogTerm 的衔接在
325		// tryApply 中单独检查。索引 0 是哨兵，真实条目索引必为正。
326		for i, entry := range request.Entries {
327			if entry.Index != request.PrevLogIndex+1+i {
328				return ReasonEntryIndexGap
329			}
330			if entry.Term <= 0 {
331				return ReasonEmptyEntryTerm
332			}
333			if i > 0 && entry.Term < request.Entries[i-1].Term {
334				return ReasonEntryTermDecreases
335			}
336			if entry.Term > request.Term {
337				return ReasonEntryTermExceedsReqTerm
338			}
339		}
340		return ReasonOK
341	}
342

