543	func resultMaps(t *testing.T, m map[string]any) []map[string]any {
544		t.Helper()
545		raw, ok := m["results"].([]any)
546		if !ok {
547			t.Fatalf("results is not an array in %v", m)
548		}
549		results := make([]map[string]any, len(raw))
550		for i, item := range raw {
551			results[i], ok = item.(map[string]any)
552			if !ok {
553				t.Fatalf("result %d is not an object: %v", i, item)
554			}
555		}
556		return results
