672	// TestKVRoundTripApplyLevelsIndependent 两层应用字段各自按本层是否出现判断：
673	// 最终结果记录了应用状态，不能让没有应用字段的请求答复凭空多出应用信息；某条
674	// 请求带有应用字段，也不能让最终结果或其他请求多出字段。同一输出中混合两种
675	// 请求答复时，读取再输出必须保留各自区别。
676	func TestKVRoundTripApplyLevelsIndependent(t *testing.T) {
677		perRequestKeys := []string{"appliedIndex", "applyError"}
678		finalKeys := []string{"finalAppliedIndex", "finalKV", "finalApplyError"}
679		cases := []struct {
680			name string
681			data string
682		}{
683			{
684				"final level applied, requests mixed plain and applied",
685				`{"results":[` +
686					`{"accepted":true,"reason":"ok","term":3,"committedIndex":0},` +
687					`{"accepted":false,"reason":"stale term: leader term is lower than current term","term":3,"committedIndex":0,"appliedIndex":2,"applyError":{"index":3,"reason":"boom"}}` +
688					`],"finalTerm":3,"finalCommittedIndex":0,"finalLog":[],` +
689					`"finalAppliedIndex":2,"finalKV":{"k":"v"},"finalApplyError":{"index":3,"reason":"boom"}}`,
690			},
691			{
692				"final level absent, requests mixed applied and plain",
693				`{"results":[` +
694					`{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"appliedIndex":0,"applyError":null},` +
695					`{"accepted":true,"reason":"ok","term":1,"committedIndex":0}` +
696					`],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`,
697			},
698		}
699		for _, tc := range cases {
700			t.Run(tc.name, func(t *testing.T) {
701				var out ReplicateOutput
702				if err := json.Unmarshal([]byte(tc.data), &out); err != nil {
703					t.Fatal(err)
704				}
705				reencoded, err := json.Marshal(out)
706				if err != nil {
707					t.Fatal(err)
708				}
709				m := decodeMap(t, reencoded)
710				results := resultMaps(t, m)
711				if len(results) != 2 {
712					t.Fatalf("expected 2 results, got %d", len(results))
713				}
714				if strings.Contains(tc.data, `"finalAppliedIndex":2`) {
715					// 第一种情形：最终层有应用字段；请求 0 无、请求 1 有。
716					mustLackKeys(t, results[0], "plain request", perRequestKeys...)
717					mustHaveKeys(t, results[1], "applied request", perRequestKeys...)
718					if results[1]["appliedIndex"] != float64(2) {
719						t.Fatalf("request appliedIndex changed: %v", results[1])
720					}
721					if !reflect.DeepEqual(results[1]["applyError"],
722						map[string]any{"index": float64(3), "reason": "boom"}) {
723						t.Fatalf("request applyError changed: %v", results[1])
724					}
725					mustHaveKeys(t, m, "final output", finalKeys...)
726					if !reflect.DeepEqual(m["finalKV"], map[string]any{"k": "v"}) {
727						t.Fatalf("finalKV changed: %v", m["finalKV"])
728					}
729				} else {
730					// 第二种情形：最终层无应用字段；请求 0 有、请求 1 无。
731					mustHaveKeys(t, results[0], "applied request", perRequestKeys...)
732					if results[0]["appliedIndex"] != float64(0) || results[0]["applyError"] != nil {
733						t.Fatalf("applied request values changed: %v", results[0])
734					}
735					mustLackKeys(t, results[1], "plain request", perRequestKeys...)
736					mustLackKeys(t, m, "final output", finalKeys...)
737				}
738			})
739		}
740	}
