769	// TestKVRoundTripFailedReuseKeepsPreviousResult 复用已有结果对象再次读入时，
770	// 类型非法的 JSON 必须明确报错，且原有结果完整保留——即使错误藏在某条请求
771	// 答复内，随后输出也不能混入这次读入的任何部分内容。
772	// TestKVRejectedReplicationKeepsApplyBoundary 回归保障：启用 applyKV 后复制请求
773	// 被拒绝时的状态边界——较高任期或较大 leaderCommit 都不能把未确认的命令写进
774	// 键值表。场景含一个已提交前缀与未提交尾部：
775	//   - 初始任期 2，idx1/idx2 任期均为 2，set balance=100 已提交而 set
776	//     balance=200 未提交：键值表只有 balance=100，应用位置停在 1；
777	//   - 任期 5 的请求把 idx2 任期错称为 3 并要求提交更后位置：因前缀不匹配被拒，
778	//     任期升到 5，但日志、提交位置、应用位置与键值表保持原值，无应用错误；
779	//   - 任期 9 但条目索引不连续的请求属于字段非法：整条拒绝且连任期都不得改变，
780	//     不能与上一种拒绝混为同样的状态变化；
781	//   - 之后任期 5、正确匹配 idx2 的合法请求追加 idx3 并提交到 3：按日志次序
782	//     应用尚未应用的命令，balance=200、receipt=ok，提交与应用位置均为 3。
783	func TestKVRejectedReplicationKeepsApplyBoundary(t *testing.T) {
784		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
785			entry(1, 2, "set balance=100"),
786			entry(2, 2, "set balance=200"), // 未提交尾部：任何拒绝都不能让它被应用
787		}}
788		wantOriginalLog := []LogEntry{
789			entry(1, 2, "set balance=100"),
790			entry(2, 2, "set balance=200"),
791		}
792	
793		// 没有请求时：只应用初始已提交前缀，字符串值原样保留。
794		start := runKV(t, initial)
795		if *start.FinalAppliedIndex != 1 {
796			t.Fatalf("initial appliedIndex = %d, want 1", *start.FinalAppliedIndex)
797		}
798		if !reflect.DeepEqual(finalKVOf(t, start), map[string]string{"balance": "100"}) {
799			t.Fatalf("initial kv = %v, want only balance=100", start.FinalKV)
800		}
801		if start.FinalApplyError != nil {
802			t.Fatalf("unexpected initial apply error: %+v", start.FinalApplyError)
803		}
804	
805		// 请求一：高任期 + 前缀任期不匹配 + 更大的 leaderCommit，其余字段全部合法。
806		mismatch := AppendRequest{Term: 5, PrevLogIndex: 2, PrevLogTerm: 3, LeaderCommit: 4,
807			Entries: []LogEntry{entry(3, 5, "set later=x")}}
808		// 请求二：任期 9，但条目索引没有从 prevLogIndex+1 开始——字段非法。
809		gap := AppendRequest{Term: 9, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 5,
810			Entries: []LogEntry{entry(4, 9, "set gap=y")}} // 期望索引 3
811		// 请求三：任期 5、正确匹配 idx2（任期 2）的合法追加。
812		legal := AppendRequest{Term: 5, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 3,
813			Entries: []LogEntry{entry(3, 5, "set receipt=ok")}}
814	
815		// 若输入停在第一次拒绝处：任期升到 5，其余一切不动，未确认命令不入表。
816		stopped := runKV(t, initial, mismatch)
817		r := stopped.Results[0]
818		if r.Accepted || r.Reason != ReasonPrevLogMismatch {
819			t.Fatalf("first request should be rejected for prefix mismatch: %+v", r)
820		}
821		if r.Term != 5 {
822			t.Fatalf("higher term should survive rejection: term = %d, want 5", r.Term)
823		}
824		if r.CommittedIndex != 1 {
825			t.Fatalf("commit advanced on rejection: %d, want 1", r.CommittedIndex)
826		}
827		if got := appliedIndexOf(t, r); got != 1 {
828			t.Fatalf("applied index advanced on rejection: %d, want 1", got)
829		}
830		if r.ApplyError != nil {
831			t.Fatalf("rejection must not produce an apply error: %+v", r.ApplyError)
832		}
833		if stopped.FinalTerm != 5 || stopped.FinalCommittedIndex != 1 {
834			t.Fatalf("final state after stop: term=%d ci=%d, want 5/1",
835				stopped.FinalTerm, stopped.FinalCommittedIndex)
836		}
837		if !reflect.DeepEqual(stopped.FinalLog, wantOriginalLog) {
838			t.Fatalf("log changed after rejection: %+v", stopped.FinalLog)
839		}
840		if *stopped.FinalAppliedIndex != 1 {
841			t.Fatalf("final appliedIndex = %d, want 1", *stopped.FinalAppliedIndex)
842		}
843		if !reflect.DeepEqual(finalKVOf(t, stopped), map[string]string{"balance": "100"}) {
844			t.Fatalf("kv changed after rejection: %v, want only balance=100", stopped.FinalKV)
845		}
846		if stopped.FinalApplyError != nil {
847			t.Fatalf("unexpected final apply error: %+v", stopped.FinalApplyError)
848		}
849	
850		// 完整过程：两种拒绝之后合法请求仍能追加并提交。
851		out := runKV(t, initial, mismatch, gap, legal)
852		wantResults := []struct {
853			accepted bool
854			reason   string
855			term     int
856			commit   int
857			applied  int
858		}{
859			{false, ReasonPrevLogMismatch, 5, 1, 1}, // 任期更新保留，其余不动
860			{false, ReasonEntryIndexGap, 5, 1, 1},   // 字段非法：连任期都停在 5
861			{true, ReasonOK, 5, 3, 3},               // 追加 idx3，提交并应用到 3
862		}
863		if len(out.Results) != len(wantResults) {
864			t.Fatalf("got %d results, want %d", len(out.Results), len(wantResults))
865		}
866		for i, want := range wantResults {
867			got := out.Results[i]
868			if got.Accepted != want.accepted || got.Reason != want.reason {
869				t.Fatalf("result %d = accepted=%v reason=%q, want accepted=%v reason=%q",
870					i, got.Accepted, got.Reason, want.accepted, want.reason)
871			}
872			if got.Term != want.term || got.CommittedIndex != want.commit {
873				t.Fatalf("result %d state = term %d ci %d, want term %d ci %d",
874					i, got.Term, got.CommittedIndex, want.term, want.commit)
875			}
876			if applied := appliedIndexOf(t, got); applied != want.applied {
877				t.Fatalf("result %d appliedIndex = %d, want %d", i, applied, want.applied)
878			}
879			if got.ApplyError != nil {
880				t.Fatalf("result %d unexpected apply error: %+v", i, got.ApplyError)
881			}
882		}
883	
884		// 最终状态：任期 5、提交 3；日志为原两条加 idx3，未提交尾部命令原样保留。
885		wantLog := []LogEntry{
886			entry(1, 2, "set balance=100"),
887			entry(2, 2, "set balance=200"),
888			entry(3, 5, "set receipt=ok"),
889		}
890		if out.FinalTerm != 5 || out.FinalCommittedIndex != 3 {
891			t.Fatalf("final replication state = term %d ci %d, want term 5 ci 3",
892				out.FinalTerm, out.FinalCommittedIndex)
893		}
894		if !reflect.DeepEqual(out.FinalLog, wantLog) {
895			t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
896		}
897		if *out.FinalAppliedIndex != 3 {
898			t.Fatalf("final appliedIndex = %d, want 3", *out.FinalAppliedIndex)
899		}
900		// 按原日志顺序应用：idx2 把 balance 改成 200，idx3 写入 receipt。
901		wantKV := map[string]string{"balance": "200", "receipt": "ok"}
902		if !reflect.DeepEqual(finalKVOf(t, out), wantKV) {
903			t.Fatalf("final kv = %v, want %v", out.FinalKV, wantKV)
904		}
905		if out.FinalApplyError != nil {
906			t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
907		}
908	}
