922	// TestKVTermConflictReplacesUncommittedSuffix 回归保障：新条目在 idx2 处与旧
923	// 日志任期冲突（旧任期 2、新任期 3）后，idx2 及其后的未提交旧后缀被整段替换；
924	// 替换区间内的新条目（idx3 任期 4）即使与旧位置同任期、命令不同，也不再逐位
925	// 比对，复制照常成功。已提交前缀 idx1 完整保留，原 idx4 被删除，最终日志只剩
926	// 三条。开启 applyKV 时提交与应用位置都推进到 3：键值表只反映新日志的命令
927	// （balance=300、receipt=ok），旧后缀中的 delete balance 与 set legacy=old
928	// 不得留下任何效果，也没有应用错误。
929	func TestKVTermConflictReplacesUncommittedSuffix(t *testing.T) {
930		out := runKV(t, uncommittedSuffixInitial(),
931			AppendRequest{Term: 4, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
932				Entries: []LogEntry{
933					entry(2, 3, "set balance=300"),
934					entry(3, 4, "set receipt=ok"), // 与旧 idx3 同任期不同命令：位于被替换后缀内，允许
935				}},
936		)
937	
938		if len(out.Results) != 1 {
939			t.Fatalf("got %d results, want 1", len(out.Results))
940		}
941		result := out.Results[0]
942		if !result.Accepted || result.Reason != ReasonOK {
943			t.Fatalf("suffix replacement should be accepted: %+v", result)
944		}
945		if result.Term != 4 || result.CommittedIndex != 3 {
946			t.Fatalf("result state = term %d ci %d, want term 4 ci 3", result.Term, result.CommittedIndex)
947		}
948		if got := appliedIndexOf(t, result); got != 3 {
949			t.Fatalf("result appliedIndex = %d, want 3", got)
950		}
951		if result.ApplyError != nil {
952			t.Fatalf("unexpected apply error: %+v", result.ApplyError)
953		}
954	
955		// 最终日志：已提交前缀保留，idx2/idx3 换成新条目，原 idx4 被删除。
956		wantLog := []LogEntry{
957			entry(1, 1, "set balance=100"),
958			entry(2, 3, "set balance=300"),
959			entry(3, 4, "set receipt=ok"),
960		}
961		if !reflect.DeepEqual(out.FinalLog, wantLog) {
962			t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
963		}
964		if out.FinalTerm != 4 || out.FinalCommittedIndex != 3 {
965			t.Fatalf("final state = term %d ci %d, want term 4 ci 3", out.FinalTerm, out.FinalCommittedIndex)
966		}
967		if *out.FinalAppliedIndex != 3 {
968			t.Fatalf("final appliedIndex = %d, want 3", *out.FinalAppliedIndex)
969		}
970		// 键值表只含新日志效果：balance=300 覆盖 100，receipt=ok 写入；
971		// 旧后缀的 delete balance 与 set legacy=old 不得生效。
972		wantKV := map[string]string{"balance": "300", "receipt": "ok"}
973		if !reflect.DeepEqual(finalKVOf(t, out), wantKV) {
974			t.Fatalf("final kv = %v, want %v (replaced suffix must not be applied)", out.FinalKV, wantKV)
975		}
976		if out.FinalApplyError != nil {
977			t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
978		}
979	}
980	
981	// TestKVSameTermConflictOnKeptPrefixRejects 回归保障相反情形：同一初始状态下，
982	// idx2 的新条目仍用任期 2（与旧条目同任期）但命令改为 set balance=300——冲突
983	// 位于仍需保留的旧日志位置，整段请求必须按同任期命令冲突拒绝。日志保持原有
984	// 四条，提交与应用位置停在 1，键值表只有 balance=100，无应用错误。
985	func TestKVSameTermConflictOnKeptPrefixRejects(t *testing.T) {
986		initial := uncommittedSuffixInitial()
987		out := runKV(t, initial,
988			AppendRequest{Term: 4, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
989				Entries: []LogEntry{
990					entry(2, 2, "set balance=300"), // 与旧 idx2 同任期不同命令：拒绝
991					entry(3, 4, "set receipt=ok"),
992				}},
993		)
994	
995		if len(out.Results) != 1 {
996			t.Fatalf("got %d results, want 1", len(out.Results))
997		}
998		result := out.Results[0]
999		if result.Accepted || result.Reason != ReasonCommandConflictSameTerm {
1000			t.Fatalf("expected same-term command conflict rejection, got %+v", result)
1001		}
1002		if result.Term != 4 || result.CommittedIndex != 1 {
1003			t.Fatalf("rejection changed state: term %d ci %d, want term 4 ci 1",
1004				result.Term, result.CommittedIndex)
1005		}
1006		if got := appliedIndexOf(t, result); got != 1 {
1007			t.Fatalf("result appliedIndex = %d, want 1", got)
1008		}
1009		if result.ApplyError != nil {
1010			t.Fatalf("rejection must not produce an apply error: %+v", result.ApplyError)
1011		}
1012	
1013		// 整条请求原子拒绝：日志、提交位置、应用位置与键值表全部保持原值。
1014		if !reflect.DeepEqual(out.FinalLog, initial.Log) {
1015			t.Fatalf("log changed after rejection: %+v", out.FinalLog)
1016		}
1017		if out.FinalTerm != 4 || out.FinalCommittedIndex != 1 {
1018			t.Fatalf("final state = term %d ci %d, want term 4 ci 1", out.FinalTerm, out.FinalCommittedIndex)
1019		}
1020		if *out.FinalAppliedIndex != 1 {
1021			t.Fatalf("final appliedIndex = %d, want 1", *out.FinalAppliedIndex)
1022		}
1023		if !reflect.DeepEqual(finalKVOf(t, out), map[string]string{"balance": "100"}) {
1024			t.Fatalf("final kv = %v, want only balance=100", out.FinalKV)
1025		}
1026		if out.FinalApplyError != nil {
1027			t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
1028		}
1029	}
1030	
1031	func TestKVRoundTripFailedReuseKeepsPreviousResult(t *testing.T) {
1032		original := runKV(t, InitialState{CurrentTerm: 1, CommittedIndex: 1, Log: []LogEntry{
1033			entry(1, 1, "set x=1"),
1034		}},
1035			AppendRequest{Term: 1, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
1036				Entries: []LogEntry{entry(2, 1, "set bad"), entry(3, 1, "set k=v")}},
1037		)
1038		originalJSON, err := json.Marshal(original)
1039		if err != nil {
1040			t.Fatal(err)
1041		}
1042		badInputs := []string{
1043			// 错误位于某条请求答复内：应用索引写成字符串。
1044			`{"results":[{"accepted":true,"reason":"ok","term":9,"committedIndex":9,"appliedIndex":"3"}],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[]}`,
1045			// 最终层：应用索引写成字符串。
1046			`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"finalAppliedIndex":"9"}`,
1047			// 最终层：键值表写成数组。
1048			`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"finalKV":["nope"]}`,
1049		}
1050		for _, bad := range badInputs {
1051			var out ReplicateOutput
1052			if err := json.Unmarshal(originalJSON, &out); err != nil {
1053				t.Fatal(err)
1054			}
1055			if err := json.Unmarshal([]byte(bad), &out); err == nil {
1056				t.Fatalf("expected decode error for %s", bad)
1057			}
1058			reencoded, err := json.Marshal(out)
1059			if err != nil {
1060				t.Fatal(err)
1061			}
1062			if string(reencoded) != string(originalJSON) {
1063				t.Fatalf("previous result not preserved after failed decode of %s:\nwant %s\n got %s",
1064					bad, originalJSON, reencoded)
1065			}
1066		}
1067	}
1068

